package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    attribute step : Integer := 0;
    perform action tick {
      first start;
      then if step < 4 {
        first start;
        then assign step := step + 1;
      } else {
        first start;
        then assign step := 0;
      }
    }
    out attribute io_0 : Boolean = (if step == 1 ? true else (if step == 2 ? false else (if step == 3 ? true else false)));
    out attribute io_1 : Boolean = (if step == 1 ? false else (if step == 2 ? true else (if step == 3 ? true else false)));
    out attribute io_2 : Boolean = (if step == 1 ? true else (if step == 2 ? true else (if step == 3 ? true else false)));
    out attribute io_3 : Boolean = (if step == 1 ? false else (if step == 2 ? false else (if step == 3 ? false else false)));
    out attribute io_4 : Boolean = (if step == 1 ? false else (if step == 2 ? true else (if step == 3 ? false else true)));
    out attribute io_5 : Boolean = (if step == 1 ? false else (if step == 2 ? true else (if step == 3 ? false else true)));
    out attribute io_6 : Boolean = (if step == 1 ? false else (if step == 2 ? true else (if step == 3 ? true else true)));
    out attribute io_7 : Boolean = false;
    out attribute io_8 : Boolean = (if step == 1 ? true else false);
    out attribute io_9 : Boolean = (if step == 2 ? true else false);
    out attribute io_10 : Boolean = (if step == 3 ? true else false);
    out attribute io_11 : Boolean = (if step == 0 ? true else (if step == 4 ? true else false));
  }
  part system : Controller;
}
